public class Notification { private final int id; private final User recipient; private final String message; private final NotificationType type; public Notification(int id,User recipient,String message,NotificationType type){this.id=id;this.recipient=recipient;this.message=message;this.type=type;} public int getId(){return id;} public User getRecipient(){return recipient;} public String getMessage(){return message;} public NotificationType getType(){return type;} }
